dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype (human)",
      "type": "list",
      "values": "cfde phenotypes"
    }
  ],
  "sections": [
    {
      "section id": "pigean_gene_set_phenotype",
      "header": "Top 20 mouse phenotypes that are genetically linked to the queried human phenotype",
      "data point": {
        "type": "bioindex",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
        "index": "pigean-gene-set-phenotype",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "pre filters": [
        {
          "field": "Source",
          "type": "search",
          "values": [
            "gene_set_list_mouse_2024",
            "komp"
          ]
        },
        {
          "field": "Source",
          "type": "filter out",
          "value": "_x_"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "phenotype probability",
            "field name": "Probability",
            "group": "trait_group",
            "rare": [
              "rare_v2"
            ],
            "common": [
              "gcat_trait",
              "portal"
            ],
            "beta": "beta_uncorrected"
          },
          {
            "type": "js math",
            "field name": "Fold-increase",
            "raw field": "beta_uncorrected",
            "method": "exp"
          },
          {
            "type": "raw",
            "field name": "hs phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "replace characters",
            "field name": "Mouse Phenotype",
            "raw field": "gene_set",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          },
          {
            "type": "raw",
            "field name": "Other human phenotypes associated with this mouse phenotype",
            "raw field": "gene_set"
          },
          {
            "type": "raw",
            "field name": "Joint effect",
            "raw field": "beta",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Marginal effect",
            "raw field": "beta_uncorrected",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Number of genes in gene set",
            "raw field": "n"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "join multi",
            "field name": "Genes in gene set",
            "fields to join": [
              "phenotype",
              "gene_set"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "Hypothesis",
            "fields to join": [
              "phenotype",
              "gene_set"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "replace characters",
            "field name": "Background",
            "raw field": "trait_group",
            "replace": [
              {
                "from": "rare_v2",
                "to": "0.005"
              },
              {
                "from": "gcat_trait",
                "to": "0.05"
              },
              {
                "from": "portal",
                "to": "0.05"
              }
            ]
          },
          {
            "type": "replace characters",
            "field name": "Background group",
            "raw field": "trait_group",
            "replace": [
              {
                "from": "rare_v2",
                "to": "rare"
              },
              {
                "from": "gcat_trait",
                "to": "common"
              },
              {
                "from": "portal",
                "to": "common"
              }
            ]
          },
          {
            "type": "raw",
            "field name": "Relative success score",
            "raw field": "rs_score"
          }
        ],
        "top rows": [
          "Mouse Phenotype",
          "Relative success score",
          "Probability",
          "Fold-increase",
          "Joint effect",
          "Marginal effect",
          "Number of genes in gene set",
          "Source",
          "Other human phenotypes associated with this mouse phenotype",
          "Genes in gene set"
        ],
        "tool tips": {
          "Other human phenotypes associated with this mouse phenotype": "Search for additional human phenotypes that are genetically linked to the mouse phenotype in each row",
          "Probability": "Probability scores are obtained from the following equation: exp(marginal effect + log(background/(1-background))) / (1 + exp(marginal effect + log(background/(1-background)))), where background estimates are 0.05 for common phenotypes and  0.005 for rare phenotypes.",
          "Fold-increase": "Scores provided from the exponential value of the marginal effect",
          "Mouse Phenotype": "Each row contains a mouse phenotype that is genetically linked to the queried human phenotype",
          "Joint effect": "The joint effect of a gene set measures its relevance to the phenotype when considered jointly across all gene sets in the model; this measure quantifies whether a gene set is maximally predictive of a phenotype compared to all other gene sets in the model. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting joint gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set. Genes with high marginal effects but weak joint effects are relevant to the phenotype in question but likely correlated with another gene set(s) that are more relevant to the phenotype.",
          "Marginal effect": "The marginal effect of a gene set measures its relevance to the phenotype when considered in isolation; this is the default measure by which the table is sorted and is the analog of traditional enrichment statistics. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting marginal gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set.",
          "Number of genes in gene set": "This shows the number of genes in the set with direct genetic support, which may be slightly higher than the total number of genes in the set (as indicated by the number of rows in the “Genes in gene set” subtable.",
          "Source": "Source of the gene set",
          "Genes in gene set": "View all genes in the gene set, sorted by relevance to the phenotype.",
          "Hypothesis": "Use GPT-4o to suggest how the 10 genes within this set most associated with the phenotype are related to the phenotype, using the gene set as context to the query. The subtable shows the response from GPT-4o as well as the input prompt, so that it can be copied into your favorite ChatBot to initiate further lines of inquiry."
        },
        "column formatting": {
          "Hypothesis": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://llm.hugeamp.org/llm?phenotype=$phenotype&gene_set=$geneSet&gene_limit=10&add_context=1",
                "parameters": [
                  "phenotype",
                  "geneSet"
                ],
                "parameters type": "replace",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Hypothesis",
                    "raw field": "gpt_response"
                  },
                  {
                    "type": "raw",
                    "field name": "LLM Query",
                    "raw field": "query"
                  }
                ],
                "top rows": [
                  "LLM Query",
                  "Hypothesis"
                ],
                "column formatting": {
                  "LLM Query": {
                    "type": [
                      "copy to clipboard"
                    ]
                  },
                  "Hypothesis": {
                    "type": [
                      "copy to clipboard"
                    ]
                  }
                }
              }
            }
          },
          "Source": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_gene_set_browser_source?source="
          },
          "Other human phenotypes associated with this mouse phenotype": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_phenotype_x_mouse2hs?mousePhenotype1=",
            "link type": "button",
            "link label": "Search"
          },
          "Genes in gene set": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
                "index": "pigean-joined-gene-set",
                "parameters": [
                  "phenotype",
                  "geneSet"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene",
                    "raw field": "gene"
                  },
                  {
                    "type": "raw",
                    "field name": "Model",
                    "raw field": "gene_set_size"
                  },
                  {
                    "type": "raw",
                    "field name": "Combined genetic support",
                    "raw field": "combined"
                  },
                  {
                    "type": "raw",
                    "field name": "Direct support",
                    "raw field": "log_bf"
                  },
                  {
                    "type": "raw",
                    "field name": "Gene set evidence",
                    "raw field": "prior"
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene",
                  "Model",
                  "Combined genetic support",
                  "Direct support",
                  "Gene set evidence"
                ],
                "column formatting": {
                  "Gene": {
                    "type": [
                      "link with parameters"
                    ],
                    "link to": "/r/kc_gene_set_browser_gene?",
                    "parameters": {
                      "gene": "Gene",
                      "model": "Model"
                    }
                  }
                }
              }
            }
          }
        }
      },
      "visualizer": {
        "label": "20 most relavant mouse phenotypes",
        "legend": "20 most relavant mouse phenotypes",
        "type": "cfde xing",
        "render by": "Mouse Phenotype",
        "threshold type": "highest n",
        "threshold": 20,
        "threshold field": "Fold-increase",
        "x axis field": "Probability",
        "suppliment field": "Fold-increase",
        "suppliment fields": [
          "Relative success score",
          "Fold-increase"
        ],
        "color by": "Background group",
        "dot colors": {
          "common": "#ff0000",
          "rare": "#3300ff"
        }
      },
      "filters unused": [
        {
          "field": "Phenotype",
          "label": "Phenotype",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Joint effect",
          "label": "Joint effect(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Marginal effect",
          "label": "Marginal effect(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Number of genes in gene set",
          "label": "Number of genes in gene set(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ],
      "citations": [
        {
          "authors": "The Common Fund Data Ecosystem Knowledge Center",
          "title": "CFDE Knowledge Center",
          "url": "https://www.cfdeknowledge.org",
          "notes": "Supported by NIH Office of the Director, Fund OT2OD036440"
        },
        {
          "authors": "The Common Fund Data Ecosystem Data Resource Center",
          "title": "CFDE Data Resource Center",
          "url": "https://info.cfde.cloud/",
          "notes": "Supported by NIH Office of the Director, Fund OT2OD036435"
        },
        {
          "authors": [
            "Cerezo M",
            "et al."
          ],
          "year": 2025,
          "title": "The NHGRI-EBI GWAS Catalog: standards for reusability, sustainability and diversity",
          "version": "Nucleic Acids Res. 2025 Jan 6;53(D1):D998–D1005",
          "url": "https://doi.org/10.1093/nar/gkae1070"
        },
        {
          "title": "Orphanet: an online rare disease and orphan drug data base",
          "organization": "INSERM",
          "year": 1999,
          "url": "https://www.orpha.net",
          "notes": "Copyright INSERM 1999"
        },
        {
          "title": "The Association to Function Knowledge Portal (A2FKP)",
          "notes": "Supported by the NHGRI under award U24HG011453"
        },
        {
          "authors": [
            "Dornbos P",
            "et al."
          ],
          "year": 2022,
          "title": "Evaluating human genetic support for hypothesized metabolic disease genes",
          "version": "Cell Metab. 2022 May 3;34(5):661-666",
          "url": [
            "https://doi.org/10.1016/j.cmet.2022.03.011",
            "https://pubmed.ncbi.nlm.nih.gov/35421386/",
            "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9166611/"
          ],
          "notes": "PMID: 35421386; PMCID: PMC9166611"
        },
        {
          "authors": [
            "Baldarelli RM",
            "Smith CL",
            "Ringwald M",
            "Richardson JE",
